function isAllowedSnapmintCheckoutHost(hostname) {
    return typeof hostname === 'string' && (hostname.endsWith('.snapmint.com') || hostname.endsWith('.snmt.link'));
}

function getValidatedCheckoutUrl(url) {
    if (!url || url === 'undefined') {
        return null;
    }

    try {
        const parsedUrl = new URL(url, window.location.origin);

        if (parsedUrl.protocol !== 'https:') {
            return null;
        }

        if (!isAllowedSnapmintCheckoutHost(parsedUrl.hostname)) {
            return null;
        }

        return parsedUrl.toString();
    } catch (err) {
        return null;
    }
}

function getEligibilityExtSid() {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }

    return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function normalize(value) {
    if (value === undefined || value === null || value === 'undefined') {
        return;
    }
    const parsed = parseInt(value, 10);
    return Number.isNaN(parsed) ? value : parsed;
}

const isValidSnapUrl = (url) => url && typeof url === 'string' && url.trim() !== '' && url !== 'undefined';

function getValue(type, isMiniCart = false) {
    const isMiniCartPage =
        isMiniCart ||
        (isValidSnapUrl(snapOptions.miniCartUrl) && window.location.href.includes(snapOptions.miniCartUrl));

    const timerConfig = {
        timer: {
            miniCart: 'miniCartTimer',
            cart: 'cartTimer',
            pdp: 'pdpTimer',
            base: 'baseTimer'
        },
        delayTime: {
            miniCart: 'miniCartDelayTime',
            cart: 'cartDelayTime',
            pdp: 'pdpDelayTime',
            base: 'baseDelayTime'
        }
    };

    const typeObj = timerConfig[type];

    if (isMiniCartPage) {
        const val = normalize(snapOptions[typeObj.miniCart]);
        if (val !== undefined) return val;
    }

    if (isValidSnapUrl(snapOptions.cartUrl) && window.location.href.includes(snapOptions.cartUrl)) {
        const val = normalize(snapOptions[typeObj.cart]);
        if (val !== undefined) return val;
    }

    const pdpVal = normalize(snapOptions[typeObj.pdp]);
    if (pdpVal !== undefined) return pdpVal;

    return normalize(snapOptions[typeObj.base]);
}

function getTimerValue(isMiniCart = false) {
    return getValue('timer', isMiniCart);
}

function getDelayTimeValue(isMiniCart = false) {
    return getValue('delayTime', isMiniCart);
}

