const mixpanelWidgetSeenWidgets = new Set();

function addingCssStyle(style, tag, number = 0) {
    let targetElement = null;
    if (tag && tag !== '#sm-widget-btn') {
        targetElement = getByIdOrClassName(tag);
    }
    if (!targetElement) {
        targetElement =
            number === 0
                ? getByIdOrClassName('#sm-widget-btn:not(.second_widget_btn)') || getByIdOrClassName(tag)
                : getByIdOrClassName('.second_widget_btn') || document.querySelectorAll(tag)[1] || null;
    }

    if (!targetElement) {
        return;
    }

    if (snapOptions.isMixpanelEventEnabled === 'true' && (tag.includes('widget') || tag.includes('minicart'))) {
        if (!mixpanelWidgetSeenWidgets.has(number)) {
            let type = getWidgetType(number);
            captureMixpanelEvent('pdp_widget_seen', {
                widget_position: number,
                widget_type: type
            });
            mixpanelWidgetSeenWidgets.add(number);
        }
    }

    let existingStyle = targetElement.querySelector('style[data-style-id="my-widget-style"]');
    if (existingStyle) {
        existingStyle.innerHTML = style;
        if (existingStyle.styleSheet) {
            existingStyle.styleSheet.cssText = style;
        }
        return;
    }

    var styleElement = document.createElement('style');
    styleElement.setAttribute('data-style-id', 'my-widget-style');
    styleElement.innerHTML = style;
    if (styleElement.styleSheet) {
        styleElement.styleSheet.cssText = style;
    } else styleElement.appendChild(document.createTextNode(style));

    targetElement.appendChild(styleElement);
    if (number !== 0) {
        targetElement.classList.add('second_widget_btn');
    }
}

function getWidgetType(number) {
    let type = 'static_widget';
    let orderVal = snapOrderValue;
    let popup = 0;

    if (snapOptions.plans) {
        for (let planIndex = 1; planIndex <= snapOptions.plans.length; planIndex++) {
            const plan = snapOptions.plans[planIndex - 1];
            if (parseFloat(orderVal) >= plan.minAmount && parseFloat(orderVal) <= plan.maxAmount) {
                popup++;
            }
        }
    }

    let popupHtml = '';
    if (number !== 0) {
        popupHtml = snapOptions['secondPopupPage' + popup] || snapOptions.secondPopupPage1 || '';
    } else {
        popupHtml = snapOptions['popupPage' + popup] || snapOptions.popupPage1 || '';
    }

    if (popupHtml) {
        if (
            popupHtml.includes('snap_eligibility_button') ||
            popupHtml.includes('snap_eligibility_text') ||
            snapOptions.changePopup.includes('snap_eligibility_button') ||
            snapOptions.changePopup.includes('snap_eligibility_text')
        ) {
            type = 'eligibility_widget';
        } else if (
            popupHtml.includes('id="fname"') ||
            popupHtml.includes('id="lname"') ||
            popupHtml.includes('id="mnumber"') ||
            popupHtml.includes('snap_first_input') ||
            popupHtml.includes('snap_second_input')
        ) {
            type = 'express_widget';
        }
    }
    return type;
}

function checkPdpIsMobile() {
    if (window.innerWidth < 768) {
        if (snapOptions.mobileDivId && snapOptions.mobileDivId !== 'undefined') {
            return true;
        }
    }
    return false;
}

function getSecondWidgetUsingPayLater(amount, widgetType, pageType) {
    if (amount && snapOptions.plans && snapOptions.plans.length > 0) {
        if (parseInt(snapOrderValue) < parseInt(snapOptions.plans[0].maxAmount)) {
            if (pageType === 'pdp') {
                return snapOptions.pdpPayLaterSecondWidget;
            }
        } else {
            return widgetType;
        }
    }
    return widgetType;
}
function loadSecondWidget() {
    let widgetPage = snapOptions.secondWidgetPage;
    let secondWidgetOrderValue = snapOrderValue;

    let parentDiv = getByIdOrClassName(snapOptions.secondDivId);
    if (checkPdpIsMobile() && snapOptions.secondMobileDivId && snapOptions.secondMobileDivId !== 'undefined') {
        parentDiv = getByIdOrClassName(snapOptions.secondMobileDivId);
    }

    if (parentDiv) {
        let priceEl = parentDiv;
        if (snapOptions.secondPriceSaleDivId && snapOptions.secondPriceSaleDivId !== 'undefined') {
            priceEl = getByIdOrClassName(snapOptions.secondPriceSaleDivId);
        } else if (snapOptions.secondPriceDivId && snapOptions.secondPriceDivId !== 'undefined') {
            priceEl = getByIdOrClassName(snapOptions.secondPriceDivId);
        }
        let textToParse = priceEl.innerText || priceEl.textContent || '';
        let parsedSecondPrice = parseNum(textToParse);
        if (!Number.isNaN(parsedSecondPrice) && parsedSecondPrice > 0) {
            secondWidgetOrderValue =
                snapOptions.isDecimalPrice === 'true'
                    ? Number(parsedSecondPrice.toFixed(2))
                    : Math.round(parsedSecondPrice);
        }
    }

    if (snapOptions.widgetPriceBreakdown && snapOptions.widgetPriceBreakdown !== 'undefined') {
        const priceArray = getPriceArray();
        widgetPage = getWidgetForPriceRange(
            secondWidgetOrderValue,
            priceArray,
            'secondWidgetPage',
            snapOptions.secondWidgetPage || snapOptions.secondWidgetPage2,
            false
        );
    } else if (snapOptions.pdpPayLaterSecondWidget && snapOptions.pdpPayLaterSecondWidget !== 'undefined') {
        widgetPage = getSecondWidgetUsingPayLater(snapOptions.pdpPayLaterAmount, snapOptions.secondWidgetPage, 'pdp');
    }

    if (document.querySelectorAll('#sm-widget-btn').length === 1) {
        if (snapOptions.secondPosition === 'before') parentDiv.insertAdjacentHTML('beforebegin', widgetPage);
        else parentDiv.insertAdjacentHTML('afterend', widgetPage);
        addingCssStyle(snapOptions.secondStyle, '#sm-widget-btn', 1);
    }

    let secondWidgetDownPayment = downPayment;
    let secondWidgetEmi = emi;
    if (snapOptions.plans && snapOptions.plans.length > 0) {
        for (let planIndex = 0; planIndex < snapOptions.plans.length; planIndex++) {
            const plan = snapOptions.plans[planIndex];
            if (secondWidgetOrderValue >= plan.minAmount && secondWidgetOrderValue <= plan.maxAmount) {
                secondWidgetDownPayment =
                    snapOptions.isDecimalPrice === 'true'
                        ? Number(((secondWidgetOrderValue * plan.dpPercent) / 100).toFixed(2))
                        : Math.round((secondWidgetOrderValue * plan.dpPercent) / 100);
                secondWidgetEmi =
                    snapOptions.isDecimalPrice === 'true'
                        ? Number((parseFloat(secondWidgetOrderValue * plan.emiPercent) / 100).toFixed(2))
                        : Math.round(parseFloat(secondWidgetOrderValue * plan.emiPercent) / 100);
            }
        }
    }

    let secondWidgetEl = getByIdOrClassName('.second_widget_btn');
    if (secondWidgetEl) {
        secondWidgetEl.setAttribute('data-widget', secondWidgetOrderValue);
        let allDpClass = secondWidgetEl.querySelectorAll('.dp-class');
        if (allDpClass.length > 0) {
            allDpClass.forEach((element) => {
                if (snapOptions.showPaywidgetEmi == 'true') {
                    element.textContent = secondWidgetEmi;
                } else element.textContent = secondWidgetDownPayment;
            });
        }
    }
}

function snapclosePopup() {
    const targetDiv = document.getElementById('sm-pop-up-model');
    if (targetDiv) {
        document.body.removeChild(targetDiv);
        document.documentElement.style.overflow = snapOptions.scrollProperty;
    }
    if (snapCloseLimitsScreenTimeout) {
        clearTimeout(snapCloseLimitsScreenTimeout);
        snapCloseLimitsScreenTimeout = null;
    }
    snapCheckoutIframeRef = null;
    snapCheckoutIframeOrigin = null;
    if (snapOptions.isTest && snapOptions.isTest === 'true') {
        if (!getByIdOrClassName(snapOptions.miniCartDivId)) {
            loadOnPage();
        }
    }
    if (snapOptions.stopScroll && snapOptions.stopScroll === 'true') {
        document.body.style.height = '';
        document.body.style.overflow = snapOptions.scrollProperty;
    }
    if (snapOptions.modalInputIsNotClickable && snapOptions.modalInputIsNotClickable !== 'undefined') {
        let element = document.querySelector(snapOptions.modalInputIsNotClickable);
        if (element) {
            element.style.visibility = 'visible';
        }
    }
}

function snapclosePopupss() {
    const targetDiv = document.getElementById('sm-pop-up-model');
    if (targetDiv) {
        document.body.removeChild(targetDiv);
    }
    if (snapCloseLimitsScreenTimeout) {
        clearTimeout(snapCloseLimitsScreenTimeout);
        snapCloseLimitsScreenTimeout = null;
    }
    snapCheckoutIframeRef = null;
    snapCheckoutIframeOrigin = null;
    if (snapOptions.modalInputIsNotClickable && snapOptions.modalInputIsNotClickable !== 'undefined') {
        let element = document.querySelector(snapOptions.modalInputIsNotClickable);
        if (element) {
            element.style.visibility = 'visible';
        }
    }
}

function replaceAllValuesInsideClass(tagName, assignValue) {
    const elements = document.getElementsByClassName(tagName);
    for (let i = 0; i < elements.length; i++) {
        elements[i].innerText = assignValue;
    }
}

function replaceValuesForNonExpress(downPayment, emi) {
    let allDownPayment = document.querySelectorAll('.downPayment');
    if (allDownPayment.length > 0) {
        allDownPayment.forEach((element) => {
            element.innerText = downPayment;
        });
    }
}

function secondWidgetClick(element) {
    if (snapOptions.pdpPayLaterSecondWidget && snapOptions.pdpPayLaterSecondWidget !== 'undefined') {
        if (element) {
            let classList = element.classList;
            if (classList.contains('second_widget_btn')) return true;
        }
    } else {
        if (element) {
            let classList = element.classList;
            if (classList.contains('second_widget_btn')) return true;
            else return false;
        }
    }
    let target = element;
    if (!target) {
        let currentEvent = typeof event !== 'undefined' ? event : null;
        if (currentEvent && currentEvent.target) {
            target = currentEvent.target;
        }
    }
    if (!target) {
        return false;
    }
    let parentNodeHave = false;
    let parentNode = target.parentNode;
    if (parentNode) parentNode = parentNode.classList;
    if (parentNode && parentNode.contains('second_widget_btn')) {
        parentNodeHave = true;
    }
    if (!parentNodeHave) {
        if (!parentNode) {
            parentNode = document.querySelector('#sm-widget-btn');
            parentNodeHave = true;
        }
        if (parentNode) parentNode = parentNode.classList;
        if (parentNode && parentNode.contains('second_widget_btn')) {
            parentNodeHave = true;
        }
        try {
            if (!parentNodeHave) {
                parentNode = target.parentNode.parentNode.parentNode;
                if (parentNode) parentNode = parentNode.classList;
                if (parentNode && parentNode.contains('second_widget_btn')) {
                    parentNodeHave = true;
                }
            }
        } catch (e) {}
    }
    return parentNodeHave;
}
